package dev.hoi.client.map;

import com.mojang.blaze3d.platform.InputConstants;
import dev.hoi.client.ClientCampaignHud;
import dev.hoi.client.screen.ScreenMapCursor;
import dev.hoi.client.ui.UiCommandLabels;
import dev.hoi.protocol.*;
import dev.hoi.protocol.ProtocolCommanderHud.*;
import net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;
import net.minecraft.client.input.MouseButtonEvent;
import net.minecraft.client.input.MouseButtonInfo;
import java.util.*;

final class MapAirBasePanelsTest {
    private static Member wing(String id,String base,int occupied,int capacity){return new Member(id,id,"대기 중","unit_hud/air_fighter","",1,new Open(Mode.AIR_MISSION,id),"",null,Map.of(),"같은 기지명","HOLD",new MemberData("","",100,null,null,true,new AirData("","","ANY",new AirBase(base,occupied-100,occupied,capacity,"KOR"),new AirWingDetails(100,"BOTH","",false,"대기 중"))));}
    static void run(ClientGameTestContext game,ProtocolMenuView menu){try{for(int[] size:List.of(new int[]{2560,1440},new int[]{1280,720})){
        var requests=new ArrayList<Open>();var view=new View[1];game.getInput().resizeWindow(size[0],size[1]);game.runOnClient(client->{client.options.guiScale().set(2);ClientCampaignHud.accept(ProtocolHudPayloads.State.of("KOR",menu.hud()));MapCommanderHud.reset();MapUnitHud.reset();MapCommanderHud.requestObserver=requests::add;view[0]=new View("KOR",client.level.dimension().identifier().toString(),Mode.AIR,List.of(),List.of(wing("a","base-a",250,400),wing("b","base-b",500,400)));MapCommanderHud.accept(view[0]);MapCommanderPanels.showWings(List.of("a","b"));});game.setScreen(ScreenMapCursor::new);game.waitTicks(3);
        game.runOnClient(client->{var closes=MapCommanderPanels.hits().stream().filter(h->h.tip().equals("선택 해제 · 같은 기지명")).sorted(Comparator.comparingInt(MapCommanderPanels.Hit::y)).toList();if(closes.size()!=2)throw new AssertionError("Different stable bases with the same label must have independent headers");var tips=MapCommanderPanels.hits().stream().map(MapCommanderPanels.Hit::tip).toList();if(tips.stream().noneMatch(t->t.contains("250")&&t.contains("400"))||tips.stream().noneMatch(t->t.contains("500")&&t.contains("400")))throw new AssertionError("Headers must show full authoritative base counts, not selected-wing totals");var cas=mission("AIRWING_MISSION_TYPE_CAS");var intercept=mission("AIRWING_MISSION_TYPE_INTERCEPTION");if(cas.x()>=intercept.x())throw new AssertionError("Native CAS then interception order required");click(cas);if(requests.size()!=1||!requests.getFirst().selection().equals(List.of("mission/CLOSE_AIR_SUPPORT","a","b")))throw new AssertionError("CAS icon must issue CAS for precisely selected wings");requests.clear();var create=MapCommanderPanels.hits().stream().filter(h->h.tip().equals(UiCommandLabels.text("AIRWING_NEW","신규 비행단 창설"))).sorted(Comparator.comparingInt(MapCommanderPanels.Hit::y)).findFirst().orElseThrow();click(create);if(requests.size()!=1||!requests.getFirst().selection().equals(List.of("action/CREATE","base/base-a")))throw new AssertionError("Base create button must bind the exact stable base");requests.clear();});game.takeScreenshot("hoi-air-independent-base-capacity-"+size[0]+"x"+size[1]+"-gui2");baseTooltip(game,size,requests);
        game.runOnClient(client->{var close=MapCommanderPanels.hits().stream().filter(h->h.tip().equals("선택 해제 · 같은 기지명")).min(Comparator.comparingInt(MapCommanderPanels.Hit::y)).orElseThrow();click(close);if(!MapCommanderPanels.commandSelection().equals(List.of("air/b"))||!requests.isEmpty())throw new AssertionError("Closing one base must only deselect its own wings");MapCommanderHud.accept(view[0]);});game.waitTicks(2);game.runOnClient(client->{if(!MapCommanderPanels.commandSelection().equals(List.of("air/b"))||MapCommanderPanels.hits().stream().filter(h->h.tip().equals("선택 해제 · 같은 기지명")).count()!=1)throw new AssertionError("Refresh must preserve scoped base deselection");if(view[0].wings().stream().anyMatch(w->!w.mission().equals("HOLD")))throw new AssertionError("Base close changed mission state");});game.takeScreenshot("hoi-air-base-deselection-preserves-other-base-"+size[0]+"x"+size[1]+"-gui2");wingControls(game,size,requests);
    }}finally{game.runOnClient(client->{MapCommanderHud.requestObserver=null;MapCommanderHud.reset();MapUnitHud.reset();});}}
    private static void wingControls(ClientGameTestContext game,int[] size,List<Open> requests){var view=new View[1];game.runOnClient(client->{view[0]=new View("KOR",client.level.dimension().identifier().toString(),Mode.AIR,List.of(),List.of(wing("a","base-a",250,400),wing("b","base-b",500,400),wing("c","base-a",250,400)));MapCommanderHud.accept(view[0]);MapCommanderPanels.showWings(List.of("a","b","c"));});game.waitTicks(2);game.runOnClient(client->{var time=MapCommanderPanels.hits().stream().filter(h->h.icon().equals("strategicair_day_night")&&h.tip().startsWith("c\n")).findFirst().orElseThrow();var commands=new ArrayList<ProtocolCommanderOrders.Command>();MapCommanderOrders.selectionObserver=q->{};MapCommanderOrders.commandObserver=commands::add;try{MapCommanderOrders.accept(new ProtocolCommanderOrders.Context(java.util.UUID.randomUUID().toString(),0,"KOR",client.level.dimension().identifier().toString(),""));click(time);}finally{MapCommanderOrders.reset();MapCommanderOrders.commandObserver=null;MapCommanderOrders.selectionObserver=null;}if(commands.size()!=1||!commands.getFirst().action().equals("AIR_SETTING/SORTIE_NEXT")||!commands.getFirst().selection().equals(List.of("c","sortie/BOTH"))||!requests.isEmpty())throw new AssertionError("Sortie button must directly cycle exactly one wing: "+commands+" "+requests);var ace=MapCommanderPanels.hits().stream().filter(h->h.icon().equals("ace_none")).findFirst().orElseThrow();click(ace);if(requests.size()!=1||requests.getFirst().mode()!=Mode.AIR_REINFORCEMENT||!requests.getFirst().target().equals("aces")||requests.getFirst().selection().size()!=1||!Set.of("a","b","c").contains(requests.getFirst().selection().getFirst()))throw new AssertionError("Ace button must open its actual wing roster only");requests.clear();var policy=MapCommanderPanels.hits().stream().filter(h->h.icon().equals("wing_prio_strip")&&h.tip().startsWith("c\n")).findFirst().orElseThrow();click(policy);if(!requests.equals(List.of(new Open(Mode.AIR_REINFORCEMENT,"policy",List.of("c")))))throw new AssertionError("Policy button must scope exactly one wing");requests.clear();var info=MapCommanderPanels.hits().stream().filter(h->h.icon().equals("unitlist_unitinfo_button")&&h.tip().equals("§ec§r\n")).findFirst().orElseThrow();click(info);if(!requests.equals(List.of(new Open(Mode.AIR_MISSION,"c"))))throw new AssertionError("Equipment portrait must open its actual wing detail");requests.clear();if(MapCommanderPanels.hits().stream().noneMatch(h->h.tip().startsWith("국가 연료")))throw new AssertionError("Native base fuel icon must expose authoritative country fuel");var close=MapCommanderPanels.hits().stream().filter(h->h.tip().equals("선택 해제 · a")).findFirst().orElseThrow();click(close);if(!Set.copyOf(MapCommanderPanels.commandSelection()).equals(Set.of("air/b","air/c"))||!requests.isEmpty())throw new AssertionError("Wing close must preserve same-base sibling and other-base selection");MapCommanderHud.accept(view[0]);});game.waitTicks(2);game.runOnClient(client->{if(!Set.copyOf(MapCommanderPanels.commandSelection()).equals(Set.of("air/b","air/c")))throw new AssertionError("Individual wing deselection did not survive refresh");});game.takeScreenshot("hoi-air-wing-controls-and-scoped-close-"+size[0]+"x"+size[1]+"-gui2");}
    private static void baseTooltip(ClientGameTestContext game,int[] size,List<Open> requests){
        var hover=new int[2];var expected=new String[1];game.runOnClient(client->{var hit=MapCommanderPanels.hits().stream().filter(h->h.tip().contains("§H150§!")&&h.tip().contains("§H250§!")).findFirst().orElseThrow();expected[0]=hit.tip();double scale=client.getWindow().getGuiScale();hover[0]=(int)Math.round((hit.x()+hit.w()/2.)*scale);hover[1]=(int)Math.round((hit.y()+hit.h()/2.)*scale);if(!expected[0].contains("\n\n")||expected[0].contains("$"))throw new AssertionError("Native base tooltip paragraphs and complete authoritative substitutions required");});
        game.getInput().setCursorPos(hover[0],hover[1]);game.waitTicks(16);game.runOnClient(client->{if(!MapCommanderHud.renderedTooltip().equals(expected[0])||!requests.isEmpty())throw new AssertionError("Base capacity hover must render current native text without issuing requests");var bounds=MapCommanderHud.tooltipBounds();if(bounds==null||bounds.x()<0||bounds.y()<0||bounds.x()+bounds.width()>client.getWindow().getGuiScaledWidth()||bounds.y()+bounds.height()>client.getWindow().getGuiScaledHeight())throw new AssertionError("Base capacity tooltip escaped GUI2 viewport");});game.takeScreenshot("hoi-air-base-capacity-native-tooltip-"+size[0]+"x"+size[1]+"-gui2");game.getInput().setCursorPos(size[0]-30,90);game.waitTicks(1);
    }
    private static MapCommanderPanels.Hit mission(String key){String name=UiCommandLabels.text(key,"");return MapCommanderPanels.hits().stream().filter(h->h.tip().startsWith(name+"\n")).findFirst().orElseThrow();}
    private static void click(MapCommanderPanels.Hit hit){var screen=net.minecraft.client.Minecraft.getInstance().gui.screen();var event=new MouseButtonEvent(hit.x()+hit.w()/2.,hit.y()+hit.h()/2.,new MouseButtonInfo(InputConstants.MOUSE_BUTTON_LEFT,0));if(!screen.mouseClicked(event,false))throw new AssertionError("Air panel click leaked to the map");screen.mouseReleased(event);}
}
